import { type RefObject, useLayoutEffect, useRef, useState } from 'react';

// The website's tab glide: SwiftUI's spring(response: 0.34, dampingFraction: 0.82) as the stiffness and damping of a
// unit mass, quick to arrive with the faintest overshoot.
const RESPONSE_S = 0.34;
const DAMPING_FRACTION = 0.82;
const STIFFNESS = ((2 * Math.PI) / RESPONSE_S) ** 2;
const DAMPING = (4 * Math.PI * DAMPING_FRACTION) / RESPONSE_S;
const STEP_S = 1 / 240;

type Box = { x: number; y: number; width: number; height: number };

const mix = (from: number, to: number, t: number) => from + (to - from) * t;

function boxWithin(element: HTMLElement, container: HTMLElement): Box {
	const rect = element.getBoundingClientRect();
	const containerRect = container.getBoundingClientRect();
	return { x: rect.left - containerRect.left, y: rect.top - containerRect.top, width: rect.width, height: rect.height };
}

function paintPill(pill: HTMLElement, box: Box) {
	pill.style.translate = `${box.x}px ${box.y}px`;
	pill.style.width = `${box.width}px`;
	pill.style.height = `${box.height}px`;
}

/**
 * Glides one pill to the tab marked `data-tab-id={activeId}` inside the pill's parent. Returns whether the pill has
 * been placed; until then the active tab draws its own surface, so the first paint matches the server render.
 */
export function useTabGlide(pillRef: RefObject<HTMLElement | null>, activeId: string) {
	const [isPlaced, setPlaced] = useState(false);
	const motion = useRef({ activeId, progress: 1, velocity: 0, frame: 0, lastTime: 0, box: null as Box | null, fromBox: null as Box | null });

	// Lands the pill on the active tab, and keeps it there when the row resizes (fonts loading, viewport).
	useLayoutEffect(() => {
		const pill = pillRef.current;
		const container = pill?.parentElement;
		if (!pill || !container) return;
		const place = () => {
			const state = motion.current;
			if (state.frame) return;
			const tab = container.querySelector<HTMLElement>(`[data-tab-id="${state.activeId}"]`);
			if (!tab) return;
			state.box = boxWithin(tab, container);
			paintPill(pill, state.box);
		};
		place();
		setPlaced(true);
		const observer = new ResizeObserver(place);
		observer.observe(container);
		return () => observer.disconnect();
	}, [pillRef]);

	useLayoutEffect(() => {
		const state = motion.current;
		const pill = pillRef.current;
		const container = pill?.parentElement;
		if ((activeId === state.activeId && !state.frame) || !pill || !container) return;

		const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
		// Starts from wherever the pill is now, which is mid-glide when tabs are switched quickly.
		state.fromBox = state.box;
		state.activeId = activeId;
		state.progress = reducedMotion ? 1 : 0;
		state.velocity = 0;
		state.lastTime = 0;

		const tick = (now: number) => {
			// Real time even at a low frame rate; the cap only stops a leap after the tab was in the background.
			const elapsed = state.lastTime ? Math.min(0.1, (now - state.lastTime) / 1000) : 1 / 60;
			state.lastTime = now;
			for (let t = 0; t < elapsed; t += STEP_S) {
				const h = Math.min(STEP_S, elapsed - t);
				state.velocity += (-STIFFNESS * (state.progress - 1) - DAMPING * state.velocity) * h;
				state.progress += state.velocity * h;
			}
			const settled = reducedMotion || (Math.abs(state.progress - 1) < 0.001 && Math.abs(state.velocity) < 0.01);
			if (settled) state.progress = 1;

			const tab = container.querySelector<HTMLElement>(`[data-tab-id="${activeId}"]`);
			if (tab) {
				const to = boxWithin(tab, container);
				const from = state.fromBox ?? to;
				// Unclamped, so the pill keeps the spring's slight overshoot.
				state.box = {
					x: mix(from.x, to.x, state.progress),
					y: mix(from.y, to.y, state.progress),
					width: mix(from.width, to.width, state.progress),
					height: mix(from.height, to.height, state.progress),
				};
				paintPill(pill, state.box);
			}
			state.frame = settled ? 0 : requestAnimationFrame(tick);
		};

		cancelAnimationFrame(state.frame);
		// The first step runs before paint, so the row never shows a frame of the new tab without its pill.
		tick(performance.now());
		return () => cancelAnimationFrame(state.frame);
	}, [activeId, pillRef]);

	return isPlaced;
}

'use client';

import { type ReactNode, useRef, useState } from 'react';
import { cx } from '@/components/ds/ui/cx';
import { useTabGlide } from './app-tab-glide';

/** An option with `href` is a link (a tab that changes the route, like ?tab=billing), so a server page can render it. */
export type AppTabOption<T extends string> = { value: T; label: ReactNode; count?: number; href?: string };

export type AppTabsProps<T extends string> = {
	value: T;
	options: Array<AppTabOption<T>>;
	/** Optional: without it the tabs keep their own selection, or follow their option hrefs. */
	onChange?: (value: T) => void;
	label: string;
	size?: 'sm' | 'md';
	/** `tabs` switches views; `radio` picks a value inside a form or a chart. Only the semantics differ. */
	kind?: 'tabs' | 'radio';
	className?: string;
};

const PILL_SURFACE = 'bg-wash/6';

/** Plain labels, with one soft gray pill, no border, that glides to the selected option on a spring. */
export function AppTabs<T extends string>({ value: controlled, options, onChange, label, size = 'md', kind = 'tabs', className }: AppTabsProps<T>) {
	const [own, setOwn] = useState(controlled);
	const value = onChange ? controlled : own;
	const pillRef = useRef<HTMLSpanElement>(null);
	const isPillPlaced = useTabGlide(pillRef, value);
	const isRadio = kind === 'radio';
	const roundClass = size === 'sm' ? 'rounded-control-sm' : 'rounded-control';

	return (
		<div role={isRadio ? 'radiogroup' : 'tablist'} aria-label={label} className={cx('relative isolate inline-flex w-fit items-center', size === 'sm' ? 'gap-0.5' : 'gap-1', className)}>
			<span ref={pillRef} aria-hidden className={cx('pointer-events-none absolute top-0 left-0 -z-10', roundClass, PILL_SURFACE, !isPillPlaced && 'invisible')} />
			{options.map((option) => {
				const isSelected = option.value === value;
				const Tag = option.href ? 'a' : 'button';
				return (
					<Tag
						key={option.value}
						{...(option.href ? { href: option.href } : { type: 'button' as const })}
						role={isRadio ? 'radio' : 'tab'}
						aria-checked={isRadio ? isSelected : undefined}
						aria-selected={isRadio ? undefined : isSelected}
						data-tab-id={option.value}
						onClick={() => (onChange ? onChange(option.value) : setOwn(option.value))}
						className={cx(
							'flex items-center gap-1.5 whitespace-nowrap outline-none duration-200 ease-out focus-visible:shadow-ring-hover motion-reduce:transition-none',
							roundClass,
							size === 'sm' ? 'h-7 px-3 text-caption' : 'h-9 px-4 text-body-sm',
							// Only the text answers a hover, so nothing fades over the pill gliding in beneath.
							isSelected ? 'text-fg transition-[color]' : 'text-fg-subtle transition-colors hover:text-fg',
							// Until the pill lands, the selected option draws the surface itself so the first paint matches.
							isSelected && !isPillPlaced && PILL_SURFACE,
						)}
					>
						{option.label}
						{option.count !== undefined && <span className={cx('tabular-nums transition-colors', isSelected ? 'text-fg-muted' : 'text-fg-subtle')}>{option.count}</span>}
					</Tag>
				);
			})}
		</div>
	);
}

export type AppSegmentedControlProps<T extends string> = Omit<AppTabsProps<T>, 'kind' | 'className'> & { label: string };

/** A single choice inside a form: the tabs' look with radio semantics. */
export function AppSegmentedControl<T extends string>(props: AppSegmentedControlProps<T>) {
	return <AppTabs kind="radio" {...props} />;
}
